def right_adjoint(l, P, Q, le_p, le_q):
    u = {}
    for b in Q:
        below = [a for a in P if le_q(l[a], b)]
        # pick the largest element of `below` (or give up), then verify
        u[b] = below[0] if below else None
    return u

