P = [0, 1, 2]
Q = [0, 1, 2, 3, 4, 5, 6]
double = {a: 2 * a for a in P}
u = right_adjoint(double, P, Q, le, le)
assert u == {0: 0, 1: 0, 2: 1, 3: 1, 4: 2, 5: 2, 6: 2}
const = {a: 3 for a in P}
assert right_adjoint(const, P, Q, le, le) is None
